const summarizeEngagementExpenses = `-- name: SummarizeEngagementExpenses :one
SELECT count(*)::bigint AS total,
       count(*) FILTER (WHERE e.approval_status = 'pending')::bigint AS pending,
       COALESCE(sum(e.amount), 0)::numeric AS amount,
       COALESCE(sum(e.tax_amount), 0)::numeric AS tax_amount
FROM expenses e
LEFT JOIN receipt_postings p ON p.organization_id = $1 AND p.engagement_id = $2
     AND p.target_type = 'expense' AND p.target_id = e.id
WHERE e.taxpayer_id = $3
  AND ($4::text IS NULL OR e.period = $4::text)
  AND ($5::text IS NULL OR e.approval_status = $5::text)
  AND ($6::text IS NULL OR p.category_code = $6::text
       OR ($6::text = '-' AND p.category_code IS NULL))
  AND ($7::text IS NULL OR e.vendor_name ILIKE '%' || $7::text || '%'
       OR e.description ILIKE '%' || $7::text || '%' OR e.receipt_number = $7::text
       OR e.vendor_tax_number = $7::text)
`

type SummarizeEngagementExpensesParams struct {
	OrganizationID int64       `json:"organization_id"`
	EngagementID   int64       `json:"engagement_id"`
	TaxpayerID     int64       `json:"taxpayer_id"`
	Period         pgtype.Text `json:"period"`
	Status         pgtype.Text `json:"status"`
	Category       pgtype.Text `json:"category"`
	Q              pgtype.Text `json:"q"`
}

type SummarizeEngagementExpensesRow struct {
	Total     int64          `json:"total"`
	Pending   int64          `json:"pending"`
	Amount    pgtype.Numeric `json:"amount"`
	TaxAmount pgtype.Numeric `json:"tax_amount"`
}

func (q *Queries) SummarizeEngagementExpenses(ctx context.Context, arg SummarizeEngagementExpensesParams) (SummarizeEngagementExpensesRow, error) {
	row := q.db.QueryRow(ctx, summarizeEngagementExpenses,
		arg.OrganizationID,
		arg.EngagementID,
		arg.TaxpayerID,
		arg.Period,
		arg.Status,
		arg.Category,
		arg.Q,
	)
	var i SummarizeEngagementExpensesRow
	err := row.Scan(
		&i.Total,
		&i.Pending,
		&i.Amount,
		&i.TaxAmount,
	)
	return i, err
}

